import { ComponentType, ReactNode } from 'react';

interface InjectedProps {
  loggedInUser: { id: string; name: string; email: string };
}

function withCurrentUser<P extends object>(
  WrappedComponent: ComponentType<P & InjectedProps>
) {
  return function WithCurrentUserComponent(
    props: Omit<P, keyof InjectedProps>
  ) {
    const currentUser = { id: 'u1', name: 'Alice', email: 'alice@example.com' };
    return <WrappedComponent {...(props as P)} loggedInUser={currentUser} />;
  };
}

// Component that needs the user prop
interface UserProfileProps {
  loggedInUser: { id: string; name: string; email: string };
  showEmail: boolean;
}

function UserProfile({ loggedInUser, showEmail }: UserProfileProps) {
  return (
    <div>
      <h2>{loggedInUser.name}</h2>
      {showEmail && <p>{loggedInUser.email}</p>}
    </div>
  );
}

// Wrap it — loggedInUser is now injected, only showEmail remains
const EnhancedProfile = withCurrentUser(UserProfile);

// Consumer only passes showEmail
<EnhancedProfile showEmail={true} />

interface AuthProps { token: string; }
interface DataProps { data: Todo[]; isLoading: boolean; }

function withAuth<P extends object>(
  Component: ComponentType<P & AuthProps>
) {
  return (props: Omit<P, keyof AuthProps>) => {
    const token = useAuthToken();
    return <Component {...(props as P)} token={token} />;
  };
}

function withData<P extends object>(
  Component: ComponentType<P & DataProps>
) {
  return (props: Omit<P, keyof DataProps>) => {
    const { data, isLoading } = useTodos();
    return <Component {...(props as P)} data={data} isLoading={isLoading} />;
  };
}

// Original component needs all injected props
interface TodoListProps {
  token: string;
  data: Todo[];
  isLoading: boolean;
  filter: 'all' | 'active' | 'done';
}

function TodoList({ token, data, isLoading, filter }: TodoListProps) {
  if (isLoading) return <div>Loading...</div>;
  return <ul>{data.filter(t => filter === 'all' || t.done === (filter === 'done')).map(...)}</ul>;
}

// Compose: each HOC removes its own injected props
const EnhancedTodoList = withAuth(withData(TodoList));

// Consumer only passes filter — token and data are injected
<EnhancedTodoList filter="active" />
